    # Collect matching files
    files = []
    for fname in os.listdir(logdir):
        full = os.path.join(logdir, fname)
        if not os.path.isfile(full):
            continue
        if fname == 'app.log':
            files.append(full)
        elif fname.startswith('app.log.'):
            suffix = fname[len('app.log.'):]
            # Must be a positive integer (with optional .gz)
            if suffix.endswith('.gz'):
                num = suffix[:-3]
            else:
                num = suffix
            try:
                n = int(num)
                if n > 0:
                    files.append(full)
            except ValueError:
                continue
    files.sort()  # deterministic order

    # Parse all entries
    # request_id -> best (latest ts) entry
    best = {}
    for fpath in files:
        for line in read_lines(fpath):
            entry = parse_json_line(line) or parse_legacy_line(line)
            if entry is None:
                continue
            rid = entry['request_id']
            if rid not in best or entry['dt'] > best[rid]['dt']:
                best[rid] = entry

    # Group failures by user
    failures = {}
    for rid, entry in best.items():
        if entry['status'] >= 500:
            user = entry['user']
            failures.setdefault(user, []).append(entry['latency_ms'])

    # Compute p95 per user
    rows = []
